/* --------------------------------------------------------------- geometry */
function layout() {
  const R = Math.min(S * 0.335, W * 0.44);          // bowl rim radius
  return {
    R,
    cx: W * 0.5,
    topY: H * 0.545,                                // rim centre height
    rimRy: R * 0.295,
    brothRx: R * 0.905, brothRy: R * 0.295 * 0.86,
    botY: H * 0.545 + R * 0.86                      // base of the bowl body
  };
}

function resize() {
  DPR = clamp(window.devicePixelRatio || 1, 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  S = Math.min(W, H);
  canvas.width = Math.round(W * DPR);
  canvas.height = Math.round(H * DPR);
  ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
  steam.length = 0;
  seedSteam();
  if (reducedMQ.matches) drawStatic();
}
window.addEventListener('resize', resize);

/* ------------------------------------------------------------------ steam */
function spawnSteam(burst) {
  const L = layout();
  const a = Math.random() * TAU, r = Math.sqrt(Math.random()) * 0.75;
  steam.push({
    x: L.cx + Math.cos(a) * r * L.brothRx,
    y: L.topY + Math.sin(a) * r * L.brothRy - L.R * 0.04,
    vx: (Math.random() - 0.5) * S * 0.008,
    vy: -(S * (burst ? 0.16 : 0.09)) * (0.7 + Math.random() * 0.6),
    size: L.R * (0.16 + Math.random() * 0.22),
    grow: L.R * (0.1 + Math.random() * 0.12),
    life: 0, max: 2.6 + Math.random() * 2.4,
    phase: Math.random() * TAU,
    spin: (Math.random() - 0.5) * 0.6,
    rot: Math.random() * TAU
  });
  if (steam.length > 130) steam.splice(0, steam.length - 130);
}
function seedSteam() {                    // start already steaming, not empty
  for (let i = 0; i < 46; i++) {
    spawnSteam(false);
    const s = steam[steam.length - 1];
    s.life = Math.random() * s.max;
    s.y += s.vy * s.life;
    s.size += s.grow * s.life;
  }
}
function addRipple(nx, ny, strength) {
  ripples.push({ x: clamp(nx, -0.85, 0.85), y: clamp(ny, -0.85, 0.85), age: 0, strength });
  if (ripples.length > 10) ripples.shift();
}

/* ------------------------------------------------------------ background */
function drawBackground(ox, oy, warm) {
  const bg = ctx.createRadialGradient(W * 0.5 + ox, H * 0.46 + oy, S * 0.05, W * 0.5, H * 0.5, S * 1.05);
  bg.addColorStop(0, '#241610');
  bg.addColorStop(0.38, '#160d08');
  bg.addColorStop(0.72, '#0b0605');
  bg.addColorStop(1, '#050303');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  /* Lantern-like warmth behind the bowl, breathing gently. */
  const L = layout();
  const haloR = L.R * 2.9;
  const halo = ctx.createRadialGradient(L.cx + ox * 0.4, L.topY - L.R * 0.5 + oy * 0.4, L.R * 0.2, L.cx, L.topY - L.R * 0.4, haloR);
  halo.addColorStop(0, 'rgba(255,166,72,' + (0.22 * warm + heat * 0.05).toFixed(3) + ')');
  halo.addColorStop(0.45, 'rgba(214,106,38,' + (0.1 * warm).toFixed(3) + ')');
  halo.addColorStop(1, 'rgba(160,64,20,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(L.cx - haloR, L.topY - L.R * 0.4 - haloR, haloR * 2, haloR * 2);

  /* Drifting motes catching the light. */
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (const d of dust) {
    const drift = reducedMQ.matches ? 0 : t * 0.006 * d.v;
    const dx = (((d.x + drift) % 1) + 1) % 1;
    const dy = (((d.y - drift * 0.6 + Math.sin(t * 0.4 + d.p) * 0.006) % 1) + 1) % 1;
    const tw = 0.35 + 0.65 * Math.abs(Math.sin(t * 0.5 * d.v + d.p));
    ctx.globalAlpha = 0.12 * tw * warm;
    const sz = d.s * S * 8;
    ctx.drawImage(puff, dx * W + ox * 0.3 - sz / 2, dy * H + oy * 0.3 - sz / 2, sz, sz);
  }
  ctx.restore();
}

function drawTable(L, ox) {
  const tableY = L.botY + L.R * 0.1;
  const tg = ctx.createLinearGradient(0, tableY - L.R * 0.06, 0, H);
  tg.addColorStop(0, '#2a1a10');
  tg.addColorStop(0.22, '#1a1009');
  tg.addColorStop(1, '#070404');
  ctx.fillStyle = tg;
  ctx.beginPath();
  ctx.ellipse(L.cx, tableY + (H - tableY) * 0.6, W * 0.75, (H - tableY) * 0.72 + L.R * 0.1, 0, 0, TAU);
  ctx.fill();

  /* Soft contact shadow, plus a warm sheen pooled in front of the bowl. */
  ctx.save();
  ctx.globalCompositeOperation = 'multiply';
  const sh = ctx.createRadialGradient(L.cx + ox, tableY, L.R * 0.2, L.cx + ox, tableY, L.R * 1.55);
  sh.addColorStop(0, 'rgba(0,0,0,0.85)');
  sh.addColorStop(0.55, 'rgba(0,0,0,0.45)');
  sh.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = sh;
  ctx.beginPath();
  ctx.ellipse(L.cx + ox, tableY, L.R * 1.55, L.R * 0.34, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  ctx.globalAlpha = 0.14;
  const sheenW = L.R * 2.3, sheenH = L.R * 0.5;
  ctx.drawImage(puff, L.cx + ox - sheenW / 2, tableY - sheenH * 0.15, sheenW, sheenH);
  ctx.restore();
}

/* ------------------------------------------------------------------- bowl */
function bowlPath(L) {
  ctx.beginPath();
  ctx.moveTo(L.cx - L.R, L.topY);
  ctx.bezierCurveTo(L.cx - L.R, L.topY + L.R * 0.46, L.cx - L.R * 0.66, L.botY - L.R * 0.1, L.cx - L.R * 0.36, L.botY);
  ctx.lineTo(L.cx + L.R * 0.36, L.botY);
  ctx.bezierCurveTo(L.cx + L.R * 0.66, L.botY - L.R * 0.1, L.cx + L.R, L.topY + L.R * 0.46, L.cx + L.R, L.topY);
  ctx.closePath();
}

function drawBowl(L, lightX) {
  /* Foot ring. */
  ctx.fillStyle = '#120d0b';
  ctx.beginPath();
  ctx.moveTo(L.cx - L.R * 0.3, L.botY - L.R * 0.02);
  ctx.lineTo(L.cx + L.R * 0.3, L.botY - L.R * 0.02);
  ctx.lineTo(L.cx + L.R * 0.26, L.botY + L.R * 0.1);
  ctx.lineTo(L.cx - L.R * 0.26, L.botY + L.R * 0.1);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,190,120,0.1)';
  ctx.fillRect(L.cx - L.R * 0.3, L.botY - L.R * 0.02, L.R * 0.6, L.R * 0.014);

  /* Glazed body: warm charcoal, lit from the pointer side. */
  const gx = L.cx + lightX * L.R * 0.5;
  const body = ctx.createRadialGradient(gx - L.R * 0.4, L.topY + L.R * 0.15, L.R * 0.2, L.cx, L.topY + L.R * 0.4, L.R * 1.35);
  body.addColorStop(0, '#4a3327');
  body.addColorStop(0.35, '#2e2018');
  body.addColorStop(0.72, '#1a120d');
  body.addColorStop(1, '#0d0806');
  bowlPath(L);
  ctx.fillStyle = body;
  ctx.fill();

  ctx.save();
  bowlPath(L);
  ctx.clip();
  /* Glaze band and a hand-painted stripe under the rim. */
  ctx.fillStyle = 'rgba(176,84,38,0.55)';
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY + L.R * 0.02, L.R, L.rimRy * 0.9, 0, 0.08 * Math.PI, 0.92 * Math.PI);
  ctx.ellipse(L.cx, L.topY - L.R * 0.02, L.R, L.rimRy * 0.9, 0, 0.92 * Math.PI, 0.08 * Math.PI, true);
  ctx.fill();
  ctx.strokeStyle = 'rgba(232,200,150,0.35)';
  ctx.lineWidth = Math.max(1, L.R * 0.008);
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY + L.R * 0.1, L.R * 0.97, L.rimRy * 1.05, 0, 0.1 * Math.PI, 0.9 * Math.PI);
  ctx.stroke();
  /* Speckle and a soft sheen sweeping the belly. */
  for (const sp of speckles) {
    ctx.globalAlpha = sp.a;
    ctx.fillStyle = '#e8c9a0';
    ctx.beginPath();
    ctx.arc(L.cx + sp.x * L.R, L.topY + sp.y * L.R, sp.s * L.R, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'screen';
  ctx.globalAlpha = 0.16;
  const sw = L.R * 1.15, sh2 = L.R * 0.62;
  ctx.drawImage(puff, gx - L.R * 0.75 - sw / 2, L.topY + L.R * 0.18, sw, sh2);
  ctx.restore();

  /* Inner wall of the rim, then the lit rim edge itself. */
  ctx.fillStyle = '#241610';
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY, L.R, L.rimRy, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255,196,128,0.5)';
  ctx.lineWidth = Math.max(1, L.R * 0.014);
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY, L.R - ctx.lineWidth / 2, L.rimRy - ctx.lineWidth / 2, 0, Math.PI * 1.05, Math.PI * 1.95);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(255,170,95,0.22)';
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY, L.R - ctx.lineWidth / 2, L.rimRy - ctx.lineWidth / 2, 0, Math.PI * 0.05, Math.PI * 0.95);
  ctx.stroke();
}

