  ctx.translate(L.cx - L.R * 0.52, L.topY - L.R * 0.05);
  ctx.rotate(-0.16 + sway);
  const w = L.R * 0.42, h = L.R * 0.5, r = L.R * 0.03;
  const g = ctx.createLinearGradient(0, -h, w * 0.4, 0);
  g.addColorStop(0, '#1d2b1c');
  g.addColorStop(0.55, '#121e12');
  g.addColorStop(1, '#0a120a');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(-w / 2 + r, 0);
  ctx.lineTo(w / 2 - r, 0); ctx.quadraticCurveTo(w / 2, 0, w / 2, -r);
