  ctx.lineTo(-w / 2 + r, -h); ctx.quadraticCurveTo(-w / 2, -h, -w / 2, -h + r);
  ctx.lineTo(-w / 2, -r); ctx.quadraticCurveTo(-w / 2, 0, -w / 2 + r, 0);
  ctx.fill();
  ctx.strokeStyle = 'rgba(170,220,150,0.16)';
  ctx.lineWidth = Math.max(1, L.R * 0.006);
