  for (const gLeaf of greens) {
    const [nx, ny] = swirled(gLeaf);
    const [x, y0] = brothXY(L, nx, ny);
    const y = y0 + bobY(gLeaf.p) * L.R * 0.008;
    const s = gLeaf.s * L.R;
    ctx.save();
    ctx.translate(x, y); ctx.rotate(gLeaf.rot); ctx.scale(1, 0.55);
