function drawBroth(L, lightX) {
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(L.cx, L.topY, L.brothRx, L.brothRy, 0, 0, TAU);
  ctx.clip();

  const bg2 = ctx.createRadialGradient(L.cx - L.R * 0.3, L.topY - L.brothRy * 0.5, L.R * 0.1, L.cx, L.topY, L.R * 1.05);
  bg2.addColorStop(0, '#c47a28');
  bg2.addColorStop(0.42, '#9a5616');
  bg2.addColorStop(0.78, '#743d0f');
  bg2.addColorStop(1, '#552a0a');
  ctx.fillStyle = bg2;
  ctx.fillRect(L.cx - L.brothRx, L.topY - L.brothRy, L.brothRx * 2, L.brothRy * 2);

