    const [x, y] = brothXY(L, nx, ny);
    ctx.fillStyle = 'rgba(176,38,18,0.55)';
    ctx.beginPath(); ctx.ellipse(x, y, c.s * L.R, c.s * L.R * 0.5, 0, 0, TAU); ctx.fill();
  }
  for (const o of oilDrops) {
    const [nx, ny] = swirled(o);
    const [x, y] = brothXY(L, nx, ny);
    const glint = reducedMQ.matches ? 0.6 : 0.45 + 0.55 * Math.abs(Math.sin(t * 1.6 + o.p));
    ctx.fillStyle = 'rgba(255,205,95,' + (0.5 * glint).toFixed(3) + ')';
    ctx.beginPath(); ctx.ellipse(x, y, o.s * L.R, o.s * L.R * 0.5, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,246,214,' + (0.75 * glint).toFixed(3) + ')';
    ctx.beginPath(); ctx.ellipse(x - o.s * L.R * 0.25, y - o.s * L.R * 0.18, o.s * L.R * 0.34, o.s * L.R * 0.18, 0, 0, TAU); ctx.fill();
