    const y = y0 + bobY(n.p) * L.R * 0.006;
    const s = n.s * L.R;
    for (let k = 0; k < 3; k++) {
      ctx.strokeStyle = k === 1 ? '#eec27a' : '#ddab54';
      ctx.lineWidth = Math.max(1.2, L.R * 0.013);
      ctx.beginPath();
      const wob = reducedMQ.matches ? 0 : Math.sin(t * 1.1 + n.p + k) * L.R * 0.006;
      for (let i = 0; i <= 16; i++) {
        const u = i / 16 - 0.5;
        const px = x + Math.cos(n.rot) * u * s * 2 - Math.sin(n.rot) * (Math.sin(u * 12 + k * 1.7) * s * 0.14 + wob);
        const py = y + Math.sin(n.rot) * u * s * 0.9 + Math.sin(u * 12 + k * 1.7) * s * 0.06 + (k - 1) * L.R * 0.012;
