    const [x, y0] = brothXY(L, nx, ny);
    const y = y0 + bobY(c.p) * L.R * 0.007;
    ctx.strokeStyle = '#e07a28';
    ctx.lineWidth = Math.max(1.2, L.R * 0.012);
    ctx.beginPath();
    ctx.moveTo(x - Math.cos(c.rot) * c.len * L.R / 2, y - Math.sin(c.rot) * c.len * L.R * 0.25);
    ctx.lineTo(x + Math.cos(c.rot) * c.len * L.R / 2, y + Math.sin(c.rot) * c.len * L.R * 0.25);
    ctx.stroke();
  }
  for (const c of corn) {
    const [nx, ny] = swirled(c);
    const [x, y0] = brothXY(L, nx, ny);
    const y = y0 + bobY(c.p) * L.R * 0.008;
    const s = c.s * L.R;
    ctx.save(); ctx.translate(x, y); ctx.rotate(c.rot);
    ctx.fillStyle = '#f0bd3a';
    ctx.beginPath(); ctx.ellipse(0, 0, s, s * 0.68, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,246,190,0.8)';
    ctx.beginPath(); ctx.ellipse(-s * 0.25, -s * 0.2, s * 0.35, s * 0.22, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }
  for (const sc of scallions) {
    const [nx, ny] = swirled(sc);
    const [x, y0] = brothXY(L, nx, ny);
    const y = y0 + bobY(sc.p) * L.R * 0.008;
    const s = sc.s * L.R;
    ctx.strokeStyle = '#6fbf4d';
    ctx.lineWidth = Math.max(1, L.R * 0.009);
    ctx.beginPath(); ctx.ellipse(x, y, s, s * 0.55, 0, 0, TAU); ctx.stroke();
    ctx.fillStyle = 'rgba(190,235,150,0.75)';
    ctx.beginPath(); ctx.ellipse(x, y, s * 0.45, s * 0.26, 0, 0, TAU); ctx.fill();
  }
  ctx.fillStyle = '#f3e2b8';
  for (const se of sesame) {
    const [nx, ny] = swirled(se);
    const [x, y] = brothXY(L, nx, ny);
    ctx.save(); ctx.translate(x, y); ctx.rotate(se.rot);
    ctx.beginPath(); ctx.ellipse(0, 0, se.s * L.R, se.s * L.R * 0.5, 0, 0, TAU); ctx.fill();
    ctx.restore();
  }

