    const fade = reducedMQ.matches ? 0.25 : Math.max(0, 1 - r.age / 1.6);
    ctx.strokeStyle = 'rgba(255,225,165,' + (0.4 * fade * r.strength).toFixed(3) + ')';
    ctx.lineWidth = Math.max(1, L.R * 0.008);
    ctx.beginPath(); ctx.ellipse(x, y, rad, rad * (L.brothRy / L.brothRx), 0, 0, TAU); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,200,120,' + (0.22 * fade * r.strength).toFixed(3) + ')';
