  rimShade.addColorStop(1, 'rgba(30,12,4,0)');
  ctx.fillStyle = rimShade;
  ctx.fillRect(L.cx - L.brothRx, L.topY - L.brothRy, L.brothRx * 2, L.brothRy * 1.4);
  ctx.restore();
}

