/* ------------------------------------------ lifted noodles and chopsticks */
function drawLifted(L, swayX, swayY) {
  const gx = L.cx + L.R * 0.2 + swayX;         // where the sticks grip the noodles
  const gy = L.topY - L.R * 0.72 + swayY;
  const sway = reducedMQ.matches ? 0 : Math.sin(t * 1.15) * L.R * 0.014 + wind * S * 0.04;

  ctx.lineCap = 'round';
  const strands = 11;
  for (let k = 0; k < strands; k++) {
    const spread = (k / (strands - 1) - 0.5);
    const startX = gx + spread * L.R * 0.1;
    const endX = L.cx + L.R * (0.08 + spread * 0.34);
    const endY = L.topY + L.R * (0.02 + Math.abs(spread) * 0.09) + (reducedMQ.matches ? 0 : Math.sin(t * 1.3 + k) * L.R * 0.005);
    const phase = k * 0.85;
    ctx.strokeStyle = k % 3 === 0 ? '#f0c87e' : (k % 3 === 1 ? '#dfae58' : '#e6bc68');
    ctx.lineWidth = Math.max(1.3, L.R * 0.016);
    ctx.beginPath();
    for (let i = 0; i <= 22; i++) {            // hanging curve, wavier near the middle
      const u = i / 22;
      const sag = Math.sin(u * Math.PI);
      const wave = Math.sin(u * 9 + phase + (reducedMQ.matches ? 0 : t * 1.6)) * L.R * 0.022 * sag;
      const px = lerp(startX, endX, u) + wave + sway * sag;
      const py = lerp(gy, endY, Math.pow(u, 0.92)) + sag * L.R * 0.05;
      if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();
    /* Broth clinging to the lowest strands. */
    if (k % 4 === 0) {
      ctx.fillStyle = 'rgba(255,205,100,0.75)';
      ctx.beginPath(); ctx.arc(endX, endY - L.R * 0.02, Math.max(1, L.R * 0.011), 0, TAU); ctx.fill();
    }
  }
  /* A wound bundle around the stick tips. */
  for (let k = 0; k < 3; k++) {
    ctx.strokeStyle = k === 1 ? '#eec27a' : '#d9a94f';
    ctx.lineWidth = Math.max(1.3, L.R * 0.017);
    ctx.beginPath();
    ctx.ellipse(gx, gy + L.R * 0.02 + k * L.R * 0.022, L.R * 0.075, L.R * 0.03, -0.25, 0, TAU);
    ctx.stroke();
  }

  /* Chopsticks reaching in from the upper right. */
  const ang = -0.82 + (reducedMQ.matches ? 0 : Math.sin(t * 0.7) * 0.012) + pointer.sy * 0.03;
  const len = L.R * 1.9;
  for (let k = 0; k < 2; k++) {
    const off = (k - 0.5) * L.R * 0.045;
    const tipX = gx + Math.cos(ang + Math.PI / 2) * off;
    const tipY = gy + Math.sin(ang + Math.PI / 2) * off;
    const endX2 = tipX + Math.cos(ang) * len;
    const endY2 = tipY + Math.sin(ang) * len;
    ctx.strokeStyle = '#2b1a10';
    ctx.lineWidth = Math.max(2.5, L.R * 0.032);
    ctx.beginPath(); ctx.moveTo(tipX, tipY); ctx.lineTo(endX2, endY2); ctx.stroke();
    ctx.strokeStyle = k === 0 ? '#6b4126' : '#7d4c2a';
    ctx.lineWidth = Math.max(1.6, L.R * 0.021);
    ctx.beginPath(); ctx.moveTo(tipX, tipY); ctx.lineTo(endX2, endY2); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,205,140,0.4)';
    ctx.lineWidth = Math.max(1, L.R * 0.007);
    ctx.beginPath();
    ctx.moveTo(tipX - L.R * 0.006, tipY - L.R * 0.006);
    ctx.lineTo(endX2 - L.R * 0.006, endY2 - L.R * 0.006);
    ctx.stroke();
  }
}

/* ------------------------------------------------------------------ steam */
function drawSteam(dt) {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = steam.length - 1; i >= 0; i--) {
    const s = steam[i];
    if (!reducedMQ.matches && dt > 0) {
      s.life += dt;
      if (s.life >= s.max) { steam.splice(i, 1); continue; }
      const curl = Math.sin(s.life * 1.7 + s.phase) * S * 0.016;
      s.x += (s.vx + curl * 0.14 + wind * S * 0.11) * dt * 3.2;
      s.y += s.vy * dt * (1 + heat * 0.25);
      s.size += s.grow * dt;
      s.rot += s.spin * dt;
      /* The pointer pushes nearby steam aside, like a hand through vapour. */
      if (pointer.seen) {
        const dx = s.x - pointer.x, dy = s.y - pointer.y;
        const d2 = dx * dx + dy * dy, rad = S * 0.16;
        if (d2 < rad * rad && d2 > 0.01) {
          const d = Math.sqrt(d2), push = (1 - d / rad) * S * 0.5 * dt;
          s.x += (dx / d) * push; s.y += (dy / d) * push * 0.6;
        }
      }
    }
    const u = s.life / s.max;
    const alpha = Math.sin(Math.min(1, u) * Math.PI) * 0.16 * (0.75 + heat * 0.45);
    if (alpha <= 0.002) continue;
    ctx.save();
    ctx.translate(s.x, s.y);
    ctx.rotate(s.rot);
    ctx.globalAlpha = alpha;
    ctx.drawImage(puff, -s.size, -s.size * 0.78, s.size * 2, s.size * 1.56);
    ctx.restore();
  }
  ctx.restore();
}

function drawVignette() {
  const v = ctx.createRadialGradient(W * 0.5, H * 0.48, S * 0.32, W * 0.5, H * 0.52, S * 1.02);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(0.65, 'rgba(0,0,0,0.22)');
  v.addColorStop(1, 'rgba(0,0,0,0.72)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);
  ctx.save();
  ctx.globalAlpha = 0.5;
  ctx.fillStyle = ctx.createPattern(grainTile, 'repeat');
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

/* -------------------------------------------------------------- main draw */
function drawFrame(dt) {
  const L = layout();
  const warm = reducedMQ.matches ? 1 : 0.94 + 0.04 * Math.sin(t * 6.7) + 0.028 * Math.sin(t * 12.9 + 1.7) + heat * 0.05;
  const ox = pointer.sx * S * 0.014;           // gentle parallax
  const oy = pointer.sy * S * 0.008;
  const L2 = { ...L, cx: L.cx + ox, topY: L.topY + oy, botY: L.botY + oy };

  drawBackground(ox, oy, warm);
  drawTable(L2, ox);
  drawBowl(L2, pointer.seen ? pointer.sx : -0.35);
  drawNori(L2, reducedMQ.matches ? 0 : Math.sin(t * 0.9) * 0.008 + wind * 0.04);
  drawBroth(L2, pointer.seen ? pointer.sx : -0.35);
  drawLifted(L2, ox * 0.6, oy * 0.6);
  drawSteam(dt);
  drawVignette();
}

function step(dt) {
  t += dt;
  pointer.sx = lerp(pointer.sx, pointer.tx, 1 - Math.exp(-dt * 4.5));
  pointer.sy = lerp(pointer.sy, pointer.ty, 1 - Math.exp(-dt * 4.5));
  wind *= Math.exp(-dt * 1.6);
  bounce *= Math.exp(-dt * 2.4);
  stirCooldown = Math.max(0, stirCooldown - dt);

  /* Hovering close to the bowl makes it steam a little harder. */
  const L = layout();
  let near = 0;
  if (pointer.seen) {
    const dx = (pointer.x - L.cx) / (L.R * 1.5), dy = (pointer.y - L.topY) / (L.R * 1.1);
    near = clamp(1.2 - Math.sqrt(dx * dx + dy * dy), 0, 1);
  }
  heat = lerp(heat, near, 1 - Math.exp(-dt * 2.5));

  /* Broth keeps a slow swirl; stirring with the pointer speeds it up. */
  swirlVel = lerp(swirlVel, 0.018, 1 - Math.exp(-dt * 0.5));
  swirl += swirlVel * dt;
  if (Math.abs(swirl) > TAU) swirl %= TAU;

  const rate = (steam.length < 42 + heat * 40) ? (5 + heat * 10) : 0;
  if (rate > 0 && Math.random() < rate * dt) spawnSteam(false);

  rippleTimer -= dt;
  if (rippleTimer <= 0) {
    rippleTimer = 1.6 + Math.random() * 2.4;
    addRipple((Math.random() - 0.5) * 1.1, (Math.random() - 0.5) * 1.1, 0.45);
  }
  for (let i = ripples.length - 1; i >= 0; i--) {
    ripples[i].age += dt;
    if (ripples[i].age > 1.6) ripples.splice(i, 1);
  }
  drawFrame(dt);
}

function loop(now) {
  if (!running) return;
  const dt = clamp((now - lastNow) / 1000 || 0, 0, 0.05);
  lastNow = now;
  step(dt);
  rafId = requestAnimationFrame(loop);
}

function drawStatic() {
  t = 1.4;
  heat = 0.35; swirl = 0.12; bounce = 0;
  pointer.sx = pointer.tx; pointer.sy = pointer.ty;
  if (ripples.length === 0) addRipple(0.15, 0.1, 0.7);
  drawFrame(0);
}

function start() {
  if (reducedMQ.matches || document.hidden) { drawStatic(); return; }
  if (running) return;
  running = true;
  lastNow = performance.now();
  rafId = requestAnimationFrame(loop);
}
function stop() {
  running = false;
  cancelAnimationFrame(rafId);
}

/* ------------------------------------------------------------- interaction */
function brothCoords(clientX, clientY) {
  const L = layout();
  return [(clientX - L.cx) / L.brothRx, (clientY - L.topY) / L.brothRy];
}

canvas.addEventListener('pointermove', (e) => {
  const dx = pointer.seen ? e.clientX - pointer.lastX : 0;
  pointer.x = e.clientX; pointer.y = e.clientY;
  pointer.lastX = e.clientX; pointer.lastY = e.clientY;
  pointer.seen = true;
  pointer.tx = clamp((e.clientX / Math.max(1, W) - 0.5) * 2, -1, 1);
  pointer.ty = clamp((e.clientY / Math.max(1, H) - 0.5) * 2, -1, 1);
  if (reducedMQ.matches) return;               // no parallax, wind or stirring
  wind = clamp(wind + dx * 0.0016, -1, 1);
  const [nx, ny] = brothCoords(e.clientX, e.clientY);
  if (nx * nx + ny * ny < 1) {                 // stirring the broth
    swirlVel = clamp(swirlVel + dx * 0.00045, -0.7, 0.7);
    if (Math.abs(dx) > 6 && stirCooldown <= 0) {
      stirCooldown = 0.35;
      addRipple(nx, ny, 0.8);
      bounce = Math.min(1, bounce + 0.35);
    }
  }
});

canvas.addEventListener('pointerdown', (e) => {
  pointer.x = e.clientX; pointer.y = e.clientY; pointer.seen = true;
  const [nx, ny] = brothCoords(e.clientX, e.clientY);
  const inside = nx * nx + ny * ny < 1.15;
  if (reducedMQ.matches) {                     // a single still frame in reply
    ripples.length = 0;
    addRipple(inside ? nx : 0, inside ? ny : 0, 1);
    drawStatic();
    return;
  }
  addRipple(inside ? nx : 0, inside ? ny : 0, 1);
  bounce = 1;
  for (let i = 0; i < 12; i++) spawnSteam(true);
});

canvas.addEventListener('pointerleave', () => {
  pointer.tx = 0; pointer.ty = 0; pointer.seen = false;
});

document.addEventListener('visibilitychange', () => {
  if (document.hidden) stop(); else start();
});
if (typeof reducedMQ.addEventListener === 'function') {
  reducedMQ.addEventListener('change', () => { stop(); resize(); start(); });
}

/* -------------------------------------------------------------------- go */
resize();
start();
</script>
</body>
</html>

