import re, sys
from html.parser import HTMLParser
path = "/app/index.html"
src = open(path, encoding="utf-8").read()
errors = []

class P(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.tags=[]; self.body_text=[]; self.in_body=False; self.in_script=False; self.in_style=False
    def handle_starttag(self,tag,attrs):
        self.tags.append((tag,dict(attrs)))
        if tag=="body": self.in_body=True
        if tag=="script": self.in_script=True
        if tag=="style": self.in_style=True
        for k,v in attrs:
            if k in ("src","href") and v: errors.append(f"external ref {tag} {k}={v}")
    def handle_endtag(self,tag):
        if tag=="body": self.in_body=False
        if tag=="script": self.in_script=False
        if tag=="style": self.in_style=False
    def handle_data(self,data):
        if self.in_body and not self.in_script and not self.in_style and data.strip():
            self.body_text.append(data.strip())

p=P(); p.feed(src); p.close()
tags=[t for t,_ in p.tags]
for bad in ("img","link","iframe","video","audio","source","object","embed","a","button","nav","form","input"):
    if bad in tags: errors.append(f"forbidden/UI tag present: {bad}")
if tags.count("canvas")!=1: errors.append(f"canvas count {tags.count('canvas')}")
if p.body_text: errors.append(f"visible body text: {p.body_text}")
for pat,label in [(r"https?://","url"),(r"@import","import"),(r"url\s*\(","css url"),(r"data:image","raster data URI"),(r"<svg","svg(none expected)"),(r"\b(fetch|XMLHttpRequest|WebSocket)\b","network call")]:
    if re.search(pat,src): errors.append(f"found {label}")
if "prefers-reduced-motion" not in src: errors.append("missing prefers-reduced-motion")
if src.count("prefers-reduced-motion")<2: errors.append("reduced-motion should appear in CSS and JS")
for need in ("requestAnimationFrame","addEventListener('pointermove'","addEventListener('pointerdown'","addEventListener('resize'","devicePixelRatio","visibilitychange"):
    if need not in src: errors.append(f"missing {need}")

# naive JS bracket balance ignoring strings, template literals, comments, regex-ish
m=re.search(r"<script>(.*)</script>",src,re.S)
if not m: errors.append("no script")
else:
    js=m.group(1); i=0; stack=[]; pairs={")":"(","]":"[","}":"{"}
    while i<len(js):
        c=js[i]
        if c=="/" and i+1<len(js) and js[i+1]=="/":
            j=js.find("\n",i); i=len(js) if j<0 else j; continue
        if c=="/" and i+1<len(js) and js[i+1]=="*":
            j=js.find("*/",i); 
            if j<0: errors.append("unterminated comment"); break
            i=j+2; continue
        if c in "'\"`":
            q=c; i+=1
            while i<len(js):
                if js[i]=="\\": i+=2; continue
                if js[i]==q: i+=1; break
                i+=1
            continue
        if c in "([{": stack.append(c)
        elif c in ")]}":
            if not stack or stack.pop()!=pairs[c]: errors.append(f"bracket mismatch at {i}"); break
        i+=1
    if stack: errors.append(f"unclosed brackets {stack}")

print(f"bytes={len(src)} lines={src.count(chr(10))+1} tags={tags}")
print("FAIL: "+"; ".join(errors) if errors else "PASS: single canvas, no visible text/UI, no external/network/raster refs, JS brackets balanced, reduced-motion + pointer + resize + DPR present")
sys.exit(1 if errors else 0)
